// Fail loudly (the error reaches WF-6) when Settings cannot be trusted: a silent default here would offer wrong or no slots, or never finish.
const f = $('Settings').first().json.fields;
if (!f) throw new Error('check_availability: the Settings table has no row');
const num = (v) => (v === null || v === undefined || String(v).trim() === '') ? NaN : Number(v);
const step = num(f.slot_step_min), lead = num(f.min_lead_min);
if (!Number.isFinite(step) || step <= 0) throw new Error('check_availability: Settings.slot_step_min must be a positive number, got ' + JSON.stringify(f.slot_step_min));
if (!Number.isFinite(lead) || lead < 0) throw new Error('check_availability: Settings.min_lead_min must be a number >= 0, got ' + JSON.stringify(f.min_lead_min));
if (typeof f.timezone !== 'string' || !f.timezone.trim() || !DateTime.now().setZone(f.timezone).isValid) throw new Error('check_availability: Settings.timezone is missing or not a valid IANA zone, got ' + JSON.stringify(f.timezone));
if (typeof f.calendar_id !== 'string' || !f.calendar_id.trim()) throw new Error('check_availability: Settings.calendar_id is missing');
let hours;
try { hours = JSON.parse(f.working_hours); } catch (e) { throw new Error('check_availability: Settings.working_hours is not valid JSON'); }
if (!hours || typeof hours !== 'object' || Array.isArray(hours)) throw new Error('check_availability: Settings.working_hours must be a JSON object keyed by mon..sun');
const hm = /^([01]\d|2[0-3]):[0-5]\d$/;
for (const [day, wh] of Object.entries(hours)) {
  if (!['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'].includes(day)) throw new Error('check_availability: Settings.working_hours has an unknown day key ' + JSON.stringify(day));
  if (wh === null || wh === false) continue; // closed day
  if (!Array.isArray(wh) || wh.length !== 2 || !hm.test(wh[0]) || !hm.test(wh[1]) || wh[0] >= wh[1]) throw new Error('check_availability: Settings.working_hours.' + day + ' must be null or ["HH:MM","HH:MM"] with open before close, got ' + JSON.stringify(wh));
}
return $input.all();

// The decision is made here, not by the model: it is handed a verdict and the exact slots that were saved for propose_booking.
// Settings were validated by Check Settings. The saved offer (Clients.last_offer_json) is {service_id, slots}: the slots are sized
// to THAT service, so propose_booking accepts a slot only for the service it was offered for. Invalid-input verdicts save
// {service_id: '', slots: []} (the saved offer mirrors the latest answer).
const s = $('Settings').first().json.fields;
const inp = $('Trigger').first().json;
const services = $('Services').all().map(i => i.json.fields || {}).filter(x => x.service_id);
const svc = services.find(x => x.service_id === String(inp.service_id || '').trim().toLowerCase());
const iso = (t) => t.toISO({ suppressMilliseconds: true });
const none = (verdict) => [{ json: { verdict, slots_local: '', offered_json: JSON.stringify({ service_id: '', slots: [] }), offered_at: DateTime.utc().toISO() } }];
if (!svc) return none('UNKNOWN_SERVICE ' + services.map(x => `${x.service_id} (${x.name}, ${x.duration_min} min)`).join('; '));
const tz = s.timezone, hours = JSON.parse(s.working_hours);
const step = Number(s.slot_step_min), lead = Number(s.min_lead_min), dur = Number(svc.duration_min);
if (!Number.isFinite(dur) || dur <= 0) throw new Error('check_availability: Services.duration_min of ' + svc.service_id + ' must be a positive number, got ' + JSON.stringify(svc.duration_min));
// FreeBusy Booked Slots: items {start, end}; the empty {} item of alwaysOutputData is dropped here. An item that has only one of the two, or an unparseable one, is not "free": throw.
const busy = $('FreeBusy').all().map(i => i.json).filter(b => b.start || b.end).map(b => {
  const bs = DateTime.fromISO(String(b.start)), be = DateTime.fromISO(String(b.end));
  if (!bs.isValid || !be.isValid) throw new Error('check_availability: unreadable busy interval from Google Calendar: ' + JSON.stringify(b));
  return { s: bs, e: be };
});
const now = DateTime.now().setZone(tz);
const day0 = DateTime.fromISO(String(inp.date || '').trim(), { zone: tz }).startOf('day');
if (!day0.isValid) return none('NONE invalid date, expected YYYY-MM-DD');
// part_of_day comes from the model: tolerate whitespace/case and the usual "no preference" words, reject anything else instead of pretending nothing is free.
const podRaw = String(inp.part_of_day == null ? '' : inp.part_of_day).trim().toLowerCase();
const pod = ['', 'any', 'anytime', 'null', 'none'].includes(podRaw) ? '' : podRaw;
if (pod && !['morning', 'afternoon', 'evening'].includes(pod)) return none('NONE invalid part_of_day, expected morning|afternoon|evening');
// morning: the visit must END by noon (a 60 min visit may start at 11:00 but not at 11:30); afternoon and evening are decided by the start.
const inPart = (t) => !pod || (pod === 'morning' && t.hour < 12 && t.plus({ minutes: dur }) <= t.set({ hour: 12, minute: 0 })) || (pod === 'afternoon' && t.hour >= 12 && t.hour < 17) || (pod === 'evening' && t.hour >= 17);
const dayKey = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
function slots(day) {
  const wh = hours[dayKey[day.weekday % 7]];
  if (!wh) return [];
  const [oh, om] = wh[0].split(':').map(Number), [ch, cm] = wh[1].split(':').map(Number);
  let t = day.set({ hour: oh, minute: om });
  const close = day.set({ hour: ch, minute: cm });
  const out = [];
  while (t.plus({ minutes: dur }) <= close) {
    const end = t.plus({ minutes: dur });
    const clash = busy.some(b => b.s < end && b.e > t);
    if (!clash && t >= now.plus({ minutes: lead })) out.push(t);
    t = t.plus({ minutes: step });
  }
  return out;
}
const today = slots(day0).filter(inPart).slice(0, 6);
let offered, verdict;
if (today.length) { offered = today; verdict = 'FREE ' + offered.map(iso).join(', '); }
else {
  offered = [];
  for (let d = 1; d <= 7 && offered.length < 3; d++) { const l = slots(day0.plus({ days: d })).filter(inPart); if (l.length) offered.push(l[0]); }
  verdict = 'NONE ' + (offered.length ? 'nearest: ' + offered.map(iso).join(', ') : 'no slots in the next 7 days');
}
// slots_local (Task 20): the same slots as the client should read them, weekday and date computed here in the clinic's
// timezone - the model wrote 'Thu, Jan 7' for Monday 2030-01-07 when it had to derive the weekday from an ISO timestamp.
const label = (t) => t.setZone(tz).toFormat("ccc, LLL d, yyyy 'at' h:mm a");
return [{ json: { verdict, slots_local: offered.map(label).join('; '), offered_json: JSON.stringify({ service_id: svc.service_id, slots: offered.map(iso) }), offered_at: DateTime.utc().toISO() } }];

// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Trigger').first().json.contact_id || '').trim();
const ok = /^(tg:\d{1,20}|wa:\+\d{1,20})$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];
